public class InnerSecurityConfigurationEncryptionConfigurationFactory(Action<Humidifier.EMRContainers.SecurityConfigurationTypes.EncryptionConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.EMRContainers.SecurityConfigurationTypes.EncryptionConfiguration>
{

    internal InnerSecurityConfigurationInTransitEncryptionConfigurationFactory InTransitEncryptionConfigurationFactory { get; set; }

    internal InnerSecurityConfigurationAtRestEncryptionConfigurationFactory AtRestEncryptionConfigurationFactory { get; set; }

    protected override Humidifier.EMRContainers.SecurityConfigurationTypes.EncryptionConfiguration Create()
    {
        var encryptionConfigurationResult = CreateEncryptionConfiguration();
        factoryAction?.Invoke(encryptionConfigurationResult);

        return encryptionConfigurationResult;
    }

    private Humidifier.EMRContainers.SecurityConfigurationTypes.EncryptionConfiguration CreateEncryptionConfiguration()
    {
        var encryptionConfigurationResult = new Humidifier.EMRContainers.SecurityConfigurationTypes.EncryptionConfiguration();

        return encryptionConfigurationResult;
    }
    public override void CreateChildren(Humidifier.EMRContainers.SecurityConfigurationTypes.EncryptionConfiguration result)
    {
        base.CreateChildren(result);

        result.InTransitEncryptionConfiguration ??= InTransitEncryptionConfigurationFactory?.Build();
        result.AtRestEncryptionConfiguration ??= AtRestEncryptionConfigurationFactory?.Build();
    }

} // End Of Class

